// PreToolUse hook (Edit|Write|NotebookEdit): blocks hand-edits to generated files.
// - Friction.xcodeproj/   -> generated by xcodegen from project.yml (CLAUDE.md rule 1)
// - testing/*.user.js     -> generated by scripts/build-userscripts.mjs (rule 2)
// Fails open: a bug in this hook must never block unrelated work.
let raw = '';
process.stdin.on('data', (c) => (raw += c));
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw || '{}');
    const ti = input.tool_input || {};
    const fp = String(ti.file_path || ti.notebook_path || '').replace(/\\/g, '/');
    let reason = '';
    if (/(^|\/)Friction\.xcodeproj(\/|$)/.test(fp)) {
      reason = 'Friction.xcodeproj is generated by xcodegen. Edit project.yml instead (CLAUDE.md rule 1).';
    } else if (/(^|\/)testing\/[^/]+\.user\.js$/.test(fp)) {
      reason = 'testing/*.user.js are generated. Edit Friction/Resources/friction.js (or the header in ' +
        'scripts/build-userscripts.mjs) and run `node scripts/build-userscripts.mjs` (CLAUDE.md rule 2).';
    }
    if (reason) {
      process.stdout.write(JSON.stringify({
        hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: reason },
      }));
    }
  } catch (_) {}
  process.exit(0);
});
